    let r2 = contains_consecutive_numbers(&v2);
    let r3 = contains_consecutive_numbers(&v3);
    let r4 = contains_consecutive_numbers(&v4);
    let r5 = contains_consecutive_numbers(&v5);
    
    assert(r1 == true);   // [1,2] and [2,3] are consecutive
    assert(r2 == false);  // No consecutive pairs
    assert(r3 == false);  // Empty array
    assert(r4 == false);  // Single element
    assert(r5 == true);   // [5,6] and [8,9] are consecutive
